import React, { useState } from 'react';

import { _t } from '../../../../languageHandler';
import AccessibleButton from '../../elements/AccessibleButton';
import Spinner from '../../elements/Spinner';
import Heading from '../../typography/Heading';
import { DeviceWithVerification } from './types';

interface Props {
    device: DeviceWithVerification;
    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
}

export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [deviceName, setDeviceName] = useState(device.display_name ?? '');
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState<string>();

    const startEditing = (): void => {
        setDeviceName(device.display_name ?? '');
        setError(undefined);
        setIsEditing(true);
    };

    const cancelEditing = (): void => {
        setDeviceName(device.display_name ?? '');
        setError(undefined);
        setIsEditing(false);
    };

    const submit = async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
        event.preventDefault();
        setError(undefined);

        if (deviceName === device.display_name) {
            setIsEditing(false);
            return;
        }

        setIsSaving(true);
        try {
            await saveDeviceName(device.device_id, deviceName);
            setIsEditing(false);
        } catch {
            setError(_t('Failed to set display name.'));
        } finally {
            setIsSaving(false);
        }
    };

    if (isEditing) {
        return <div
            className='mx_DeviceDetailHeading mx_DeviceDetailHeading_edit'
            data-testid='device-detail-heading-edit'
        >
            <form onSubmit={submit}>
                <label htmlFor={`device-detail-name-${device.device_id}`}>
                    { _t('Session name') }
                </label>
                <input
                    id={`device-detail-name-${device.device_id}`}
                    data-testid='device-detail-name-input'
                    type='text'
                    value={deviceName}
                    maxLength={100}
                    autoComplete='off'
                    autoFocus
                    onChange={event => setDeviceName(event.target.value)}
                    disabled={isSaving}
                />
                <p className='mx_DeviceDetailHeading_note'>
                    { _t('Session names may be visible to other people you communicate with.') }
                </p>
                { error && <p
                    className='mx_DeviceDetailHeading_error'
                    role='alert'
                    data-testid='device-detail-name-error'
                >
                    { error }
                </p> }
                <div className='mx_DeviceDetailHeading_actions'>
                    <AccessibleButton
                        element='button'
                        type='submit'
                        kind='primary'
                        disabled={isSaving}
                        data-testid='device-detail-save'
                        onClick={() => undefined}
                    >
                        { _t('Save') }
                        { isSaving && <span data-testid='device-detail-saving-spinner'>
                            <Spinner w={16} h={16} />
                        </span> }
                    </AccessibleButton>
                    <AccessibleButton
                        element='button'
                        type='button'
                        kind='link'
                        disabled={isSaving}
                        data-testid='device-detail-cancel'
                        onClick={cancelEditing}
                    >
                        { _t('Cancel') }
                    </AccessibleButton>
                </div>
            </form>
        </div>;
    }

    return <div className='mx_DeviceDetailHeading mx_DeviceDetailHeading_read' data-testid='device-detail-heading'>
        <Heading size='h3' data-testid='device-detail-heading-name'>
            { device.display_name ?? device.device_id }
        </Heading>
        <AccessibleButton
            kind='link_inline'
            onClick={startEditing}
            data-testid='device-detail-rename'
        >
            { _t('Rename') }
        </AccessibleButton>
    </div>;
};
};

export enum OwnDevicesError {
    Unsupported = 'Unsupported',
    Default = 'Default',
}
export type DevicesState = {
    devices: DevicesDictionary;
    currentDeviceId: string;
    isLoading: boolean;
    // not provided when current session cannot request verification
    requestDeviceVerification?: (deviceId: DeviceWithVerification['device_id']) => Promise<VerificationRequest>;
    refreshDevices: () => Promise<void>;
    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
    error?: OwnDevicesError;
};
export const useOwnDevices = (): DevicesState => {
    const matrixClient = useContext(MatrixClientContext);

    const currentDeviceId = matrixClient.getDeviceId();
    const userId = matrixClient.getUserId();

    const [devices, setDevices] = useState<DevicesState['devices']>({});
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<OwnDevicesError>();

    const refreshDevices = useCallback(async () => {
        setIsLoading(true);
        try {
            // realistically we should never hit this
            // but it satisfies types
            if (!userId) {
                throw new Error('Cannot fetch devices without user id');
            }
            const devices = await fetchDevicesWithVerification(matrixClient, userId);
            setDevices(devices);
            setIsLoading(false);
        } catch (error) {
            if ((error as MatrixError).httpStatus == 404) {
                // 404 probably means the HS doesn't yet support the API.
                setError(OwnDevicesError.Unsupported);
            } else {
                logger.error("Error loading sessions:", error);
                setError(OwnDevicesError.Default);
            }
            setIsLoading(false);
        }
    }, [matrixClient, userId]);

    const saveDeviceName = useCallback(async (deviceId: string, deviceName: string): Promise<void> => {
        try {
            await matrixClient.setDeviceDetails(deviceId, { display_name: deviceName });
            setDevices(currentDevices => {
                const device = currentDevices[deviceId];
                if (!device) {
                    return currentDevices;
                }
                return {
                    ...currentDevices,
                    [deviceId]: {
                        ...device,
                        display_name: deviceName,
                    },
                };
            });
        } catch (error) {
            logger.error("Error setting session display name", error);
            throw new Error("Failed to set display name.");
        }
    }, [matrixClient]);

    useEffect(() => {
        refreshDevices();
    }, [refreshDevices]);

    const isCurrentDeviceVerified = !!devices[currentDeviceId]?.isVerified;

    const requestDeviceVerification = isCurrentDeviceVerified && userId
        ? async (deviceId: DeviceWithVerification['device_id']) => {
            return await matrixClient.requestVerification(
                userId,
                [deviceId],
            );
        }
        : undefined;

    return {
        devices,
        currentDeviceId,
        requestDeviceVerification,
        refreshDevices,
        saveDeviceName,
        isLoading,
        error,
    };
};
